('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Which of the following is a CHEMICAL change?', 'Dissolving sugar in water', 'Melting ice cream', 'Cutting paper', 'Rotting of tomatoes', 'D', 'Rotting forms new substances; others only change appearance.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Which shows ONLY a PHYSICAL change?', 'Crushing chunks of ice', 'Rusting of iron', 'Burning wood', 'Milk turning sour', 'A', 'Ice is still water; no new substance formed.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'What is the MAIN difference between chemical and physical change?', 'Physical change cannot be reversed', 'Physical change always releases heat', 'Chemical change produces a NEW substance', 'Chemical change is always faster', 'C', 'Composition changes in chemical change; stays the same in physical.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Which of these is a CHEMICAL change?', 'Opening a soda can', 'Photosynthesis in plants', 'Painting wood', 'Bending metal', 'B', 'Plants turn CO₂ and water into glucose and oxygen.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Bubbles forming when vinegar is mixed with baking soda is evidence of:', 'Evolution of gas', 'Color change', 'Physical change only', 'Precipitate formation', 'A', 'Bubbles indicate CO₂ gas is released.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Curdling of milk into lumpy solids is an example of which evidence?', 'Temperature drop only', 'Gas evolution', 'Production of light', 'Formation of a precipitate', 'D', 'A precipitate is an insoluble solid formed during a reaction.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Mixing quicklime and water makes the container feel hot. What evidence is this?', 'Color change', 'Change in temperature', 'Gas formation', 'Precipitate formation', 'B', 'Heat released indicates an exothermic chemical reaction.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Which is NOT evidence that a chemical reaction occurred?', 'Production of light (like burning)', 'Formation of gas bubbles', 'Change in shape only by cutting', 'Change in color', 'C', 'Cutting changes only the shape, not the substance.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'A student mixes two clear liquids and a yellow solid settles at the bottom. This is:', 'Precipitate formation', 'Physical change', 'Gas evolution', 'Boiling', 'A', 'Formation of a solid from two liquids is a precipitate.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'In a chemical equation, substances on the LEFT side of the arrow are called:', 'Coefficients', 'Products', 'Precipitates', 'Reactants', 'D', 'Reactants are the starting substances.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'Substances written on the RIGHT side of the arrow are:', 'Symbols only', 'Products', 'Reactants', 'Gases always', 'B', 'Products are the new substances formed.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'What does the symbol (aq) mean in a chemical equation?', 'Solid precipitate', 'Gaseous state', 'Dissolved in water (aqueous)', 'Liquid pure substance', 'C', 'Aqueous means dissolved in water.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'The symbol Δ written above the arrow means:', 'Heat is supplied to the reaction', 'Gas is released', 'A precipitate forms', 'Reaction is reversible', 'A', 'Δ indicates heat is added.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'The downward arrow (↓) next to a product means:', 'Heat released', 'Gas evolved', 'Liquid product', 'A solid precipitate was formed', 'D', 'The downward arrow indicates a precipitate.', true),
('b0000000-0000-0000-0000-000000000101', 1, 'pre_test', 'What does the + sign between reactants mean?', 'Heat is added', 'Substances are mixed / added together', '"Yields" or "produces"', 'Only one reacts', 'B', 'The plus sign means "reacts with" or "and."', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'Which general equation represents COMBINATION (Synthesis)?', 'AB + CD → AD + CB', 'A + B → AB', 'AB → A + B', 'AB + C → AC + B', 'B', 'Two or more reactants form ONE product.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', '2Na + Cl₂ → 2NaCl is an example of:', 'Single displacement', 'Combustion', 'Decomposition', 'Combination', 'D', 'Na + Cl combine to make one product, NaCl.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'The reaction CaCO₃ → CaO + CO₂ is classified as:', 'Combination', 'Double displacement', 'Decomposition', 'Acid-base reaction', 'C', 'One reactant breaks down into two simpler substances.', true),
('b0000000-0000-0000-0000-000000000104', 1, 'post_test', 'What is the general form of DECOMPOSITION?', 'AB + C → AC + B', 'Acid + Base → Salt + Water', 'A + B → AB', 'AB → A + B', 'D', 'Opposite of combination; one becomes two or more substances.', true),
